import{_ as o,o as s,c as t,a2 as r}from"./chunks/framework.D66Xq0Kv.js";const h=JSON.parse('{"title":"Models","description":"","frontmatter":{"title":"Models"},"headers":[],"relativePath":"docs/settings/models.md","filePath":"docs/settings/models.md","lastUpdated":1794188847000}'),d={name:"docs/settings/models.md"};function a(n,e,l,i,m,c){return s(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="models" tabindex="-1">Models <a class="header-anchor" href="#models" aria-label="Permalink to &quot;Models&quot;">​</a></h1><p>Settings → Models is where you choose the AI models OrbySystems uses. See <a href="/docs/concepts/llm-models">LLM models</a> for the ideas behind them; this page covers the settings.</p><h2 id="trusted-models" tabindex="-1">Trusted Models <a class="header-anchor" href="#trusted-models" aria-label="Permalink to &quot;Trusted Models&quot;">​</a></h2><p><strong>OrbySystems Small</strong>, <strong>OrbySystems Medium</strong> and <strong>OrbySystems Large</strong> are the models OrbySystems is built and tested for. They run on your computer. The one that suits your computer&#39;s memory is recommended, and it&#39;s downloaded the first time it&#39;s needed. See <a href="/docs/overview/hardware-requirements">Hardware requirements</a> for which one your computer gets, and <a href="/docs/getting-started/install-orby">Install OrbySystems</a> for what to expect the first time.</p><h2 id="open-source-and-cloud-models" tabindex="-1">Open Source and Cloud Models <a class="header-anchor" href="#open-source-and-cloud-models" aria-label="Permalink to &quot;Open Source and Cloud Models&quot;">​</a></h2><p>If you want a different chat model, choose one here: a larger open-source model that runs on your computer, or a model you connect through a local server (such as LM Studio) or a cloud provider. The model you choose reads your data just as the OrbySystems models do, and a cloud model receives every message you send. OrbySystems isn&#39;t tested with these models, so its answers can be less reliable. This is entirely optional: OrbySystems works fully offline.</p><h2 id="embedding-model" tabindex="-1">Embedding Model <a class="header-anchor" href="#embedding-model" aria-label="Permalink to &quot;Embedding Model&quot;">​</a></h2><p><strong>OrbySystems Embedding</strong> indexes your documents and memory so OrbySystems can search and recall them. It runs on your computer, alongside the chat model.</p><h2 id="open-source-and-cloud-embedding-models" tabindex="-1">Open Source and Cloud Embedding Models <a class="header-anchor" href="#open-source-and-cloud-embedding-models" aria-label="Permalink to &quot;Open Source and Cloud Embedding Models&quot;">​</a></h2><p>You can choose a different embedding model: an open-source one that runs on your computer, or one you connect through a local server or a cloud provider. A cloud one is sent the text it indexes from your documents and transactions.</p><h2 id="before-you-rely-on-a-model" tabindex="-1">Before you rely on a model <a class="header-anchor" href="#before-you-rely-on-a-model" aria-label="Permalink to &quot;Before you rely on a model&quot;">​</a></h2><p>Use <a href="/docs/tools/model-test">Model Test</a> to confirm a newly configured model works correctly with OrbySystems.</p>',12)])])}const y=o(d,[["render",a]]);export{h as __pageData,y as default};
